// DRY VIOLATION: email validation logic duplicated
class UserService {
    boolean isValidEmail(String e) { return e != null && e.contains("@"); }
}
class OrderService {
    boolean isValidEmail(String e) { return e != null && e.contains("@"); } // copy-paste!
}

// DRY fix: extract to shared utility
class EmailValidator {
    public static boolean isValid(String e) { return e != null && e.contains("@"); }
}
// Both services use EmailValidator.isValid() — logic lives in one place
